create table if not exists "server_plugin_script_runs" ("id" text not null primary key, "plugin_id" text not null, "trigger" text not null check (trigger in ('manual', 'scheduled')), "status" text not null check (status in ('failed', 'succeeded')), "input_json" text, "result_json" text, "error_message" text, "started_at" integer not null, "completed_at" integer not null, constraint "fk_server_plugin_script_runs_plugin_id" foreign key ("plugin_id") references "server_plugin_scripts" ("plugin_id") on delete cascade);
create index if not exists "idx_server_plugin_script_runs_plugin_started" on "server_plugin_script_runs" ("plugin_id", "started_at" desc)
